content.content:
Ubuntu 24.04.4 LTS
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name origin-simplemap.safecast.org;

    ssl_certificate /etc/letsencrypt/live/simplemap.safecast.org/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/simplemap.safecast.org/privkey.pem;
    include /etc/letsencrypt/options-ssl-nginx.conf;
    ssl_dhparam /etc/letsencrypt/ssl-dhparams.pem;

    # MCP Server SSE transport
    location /mcp {
        proxy_pass http://localhost:3333;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 86400;
    }

    # MCP Server HTTP transport (used by Claude.ai and other MCP clients)
    location /mcp-http {
        proxy_pass http://localhost:3333;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # Safecast Web Chat (MCP + Claude streaming)
    location /assistant/ {
        proxy_pass http://localhost:3334/;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_buffering off;
        proxy_read_timeout 120s;
        proxy_cache off;
    }

    # MCP REST API documentation
    location /docs/ {
        proxy_pass http://localhost:3333/docs/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }


    # Map server API routes (auth, user, admin) — before /api/ to take priority
    location /api/auth/ {
        proxy_pass http://localhost:8765;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    location /api/user/ {
        proxy_pass http://localhost:8765;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    location /api/admin/ {
        proxy_pass http://localhost:8765;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        client_max_body_size 100M;
    }

    # MCP REST API — only route MCP-specific endpoints to port 3333
    location = /api/radiation  { proxy_read_timeout 120; proxy_pass http://localhost:3333/api/radiation; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; }
    location = /api/area       { proxy_read_timeout 120; proxy_pass http://localhost:3333/api/area; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; }
    location = /api/sensors    { proxy_read_timeout 120; proxy_pass http://localhost:3333/api/sensors; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; }
    location /api/sensor/      { proxy_read_timeout 120; proxy_pass http://localhost:3333/api/sensor/; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; }
    location /api/device/      { proxy_read_timeout 120; proxy_pass http://localhost:3333/api/device/; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; }
    location = /api/spectra    { proxy_read_timeout 120; proxy_pass http://localhost:3333/api/spectra; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; }
    location = /api/stats      { proxy_read_timeout 120; proxy_pass http://localhost:3333/api/stats; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; }
    location = /api/extreme    { proxy_read_timeout 120; proxy_pass http://localhost:3333/api/extreme; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; }
    location /api/info/        { proxy_read_timeout 120; proxy_pass http://localhost:3333/api/info/; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; }
    location /api/gpt/         { proxy_read_timeout 120; proxy_pass http://localhost:3333/api/gpt/; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; }
    location ~ ^/api/track/[^/]+/insights { proxy_read_timeout 120; proxy_pass http://localhost:8765; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; }
    location /api/track/       { proxy_read_timeout 120; proxy_pass http://localhost:3333/api/track/; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; }

    # Everything else (map app, /static/, etc.) goes to the map server
    location / {
        proxy_pass http://localhost:8765;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        client_max_body_size 100M;
    }
}

