content = open('/etc/nginx/sites-available/origin-simplemap.safecast.org').read()

old = '''    # MCP REST API documentation
    location /docs/ {
        proxy_pass http://localhost:3333/docs/;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
    }'''

new = '''    # MCP REST API documentation (Swagger UI served at /mcp-api/ on port 3333)
    location /mcp-api/ {
        proxy_pass http://localhost:3333/mcp-api/;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
    }

    # Redirect legacy /docs/ to /mcp-api/
    location = /docs/ {
        return 301 /mcp-api/;
    }'''

if old in content:
    content = content.replace(old, new)
    open('/etc/nginx/sites-available/origin-simplemap.safecast.org', 'w').write(content)
    print('OK: replaced')
else:
    print('ERROR: pattern not found')
    print(repr(content[content.find('MCP REST'):content.find('MCP REST')+300]))
PYEOF
python3 /tmp/nginx_patch.py"

